after.content:
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Push-Location $root
try {
  & .\gradlew.bat stage2Check --offline --rerun-tasks
  if ($LASTEXITCODE -ne 0) { throw "Stage 2 offline gate failed: $LASTEXITCODE" }
  & pwsh -NoProfile -File .\scripts\windows-workspace-tool-smoke.ps1
  if ($LASTEXITCODE -ne 0) { throw "Stage 2 Windows native smoke failed: $LASTEXITCODE" }
} finally {
  Pop-Location
}
